//! Transitions and build steps read from tests/corpus/pptx/anim.pptx
//! (generated by scripts/corpus/gen_pptx_anim.py), and kept through an
//! edit and a save.

use std::path::PathBuf;

use slides_engine::anim::{Dir, EffectClass, Preset, Target, TransitionKind, Trigger};
use slides_engine::{Presentation, Xfrm};

fn open() -> Presentation {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/corpus/pptx/anim.pptx");
    Presentation::open(&path).unwrap()
}

fn id(p: &Presentation, slide: usize, name: &str) -> u32 {
    p.slide(slide)
        .shapes
        .iter()
        .find(|s| s.name == name)
        .unwrap_or_else(|| panic!("no {name}"))
        .id
}

#[test]
fn transitions() {
    let p = open();
    let t = p.slide(0).show_fx().transition.unwrap();
    assert_eq!(
        (t.kind, t.through, t.duration_ms),
        (TransitionKind::Fade, None, 500)
    );
    assert!(t.advance_on_click);

    let t = p.slide(1).show_fx().transition.unwrap();
    assert_eq!(t.kind, TransitionKind::Push(Dir::Up));
    assert_eq!((t.duration_ms, t.advance_after_ms), (1000, Some(3000)));

    // The PowerPoint 2010 transition, not the fallback.
    let t = p.slide(2).show_fx().transition.unwrap();
    assert_eq!(t.kind, TransitionKind::Push(Dir::Up));
    assert_eq!((t.duration_ms, t.source.as_str()), (1250, "p14:pan"));

    let t = p.slide(3).show_fx().transition.unwrap();
    assert_eq!(
        t.kind,
        TransitionKind::Split {
            vertical: true,
            out: false
        }
    );
}

#[test]
fn build_steps() {
    let p = open();
    let (a, b, c) = (id(&p, 1, "Box A"), id(&p, 1, "Box B"), id(&p, 1, "Box C"));
    let fx = p.slide(1).show_fx();
    assert_eq!(fx.steps.len(), 2);
    // Box A fades in by itself after the transition.
    assert!(fx.steps[0].auto);
    let e = &fx.steps[0].effects;
    assert_eq!(e.len(), 1);
    assert_eq!(
        (e[0].target, e[0].class, e[0].preset, e[0].trigger),
        (
            Target::Shape(a),
            EffectClass::Entrance,
            Preset::Fade,
            Trigger::AfterPrevious
        )
    );
    assert_eq!(e[0].dur_ms, 500);
    // Click 1: B flies in from the bottom, C wipes in from the left with
    // it, then A fades out.
    assert!(!fx.steps[1].auto);
    let e = &fx.steps[1].effects;
    let got: Vec<_> = e
        .iter()
        .map(|e| (e.target, e.class, e.preset, e.trigger, e.start_ms))
        .collect();
    assert_eq!(
        got,
        [
            (
                Target::Shape(b),
                EffectClass::Entrance,
                Preset::Fly(Dir::Up),
                Trigger::OnClick,
                0
            ),
            (
                Target::Shape(c),
                EffectClass::Entrance,
                Preset::Wipe(Dir::Right),
                Trigger::WithPrevious,
                250
            ),
            (
                Target::Shape(a),
                EffectClass::Exit,
                Preset::Fade,
                Trigger::AfterPrevious,
                750
            ),
        ]
    );
    assert_eq!(fx.steps[1].duration_ms(), 1250);
    for t in [a, b, c] {
        assert!(fx.starts_hidden(Target::Shape(t)), "{t}");
    }
    assert!(!fx.starts_hidden(Target::Shape(id(&p, 1, "Title 1"))));
    // Slide 1 has no builds.
    assert!(p.slide(0).show_fx().steps.is_empty());
}

#[test]
fn paragraph_builds_and_fallbacks() {
    let p = open();
    let body = id(&p, 2, "Content Placeholder 2");
    let fx = p.slide(2).show_fx();
    assert_eq!(fx.steps.len(), 3);
    for (i, s) in fx.steps.iter().enumerate() {
        assert_eq!(s.effects.len(), 1);
        assert_eq!(s.effects[0].target, Target::Para(body, i as u32));
    }
    assert!(fx.by_paragraph(body));
    assert_eq!(
        fx.hidden_at_start(),
        [
            Target::Para(body, 0),
            Target::Para(body, 1),
            Target::Para(body, 2)
        ]
    );
    assert!(!fx.starts_hidden(Target::Shape(body)));

    // Rise Up (37) isn't drawn: it fades; Collapse (21 exit) disappears.
    let odd = id(&p, 3, "Odd one");
    let fx = p.slide(3).show_fx();
    assert_eq!(fx.steps.len(), 2);
    assert_eq!(fx.steps[0].effects[0].preset, Preset::Fade);
    assert_eq!(fx.steps[0].effects[0].preset_id, 37);
    assert_eq!(fx.steps[1].effects[0].preset, Preset::Appear);
    assert_eq!(fx.steps[1].effects[0].class, EffectClass::Exit);
    assert!(fx.starts_hidden(Target::Shape(odd)));
}

#[test]
fn kept_through_edits_and_saves() {
    let mut p = open();
    let before: Vec<_> = (0..p.len()).map(|i| p.slide(i).show_fx()).collect();
    let b = p
        .slide(1)
        .shapes
        .iter()
        .position(|s| s.name == "Box B")
        .unwrap();
    p.set_xfrm((1, b), Xfrm::new(914_400, 914_400, 914_400, 914_400), false)
        .unwrap();
    let bytes = p.to_bytes().unwrap();
    let q = Presentation::from_bytes(bytes).unwrap();
    let after: Vec<_> = (0..q.len()).map(|i| q.slide(i).show_fx()).collect();
    assert_eq!(before, after);
}
